/**
 * The honest anchors beside a yearly price (owner's pricing rules,
 * 2026-10-23): only comparisons between prices that are really on sale
 * today, worked out from the amounts the screen itself shows.
 *
 * - Twelve monthly payments against the yearly price ("12 monthly
 *   payments: $59.88").
 * - How many months of the monthly plan a year costs ("12 months for
 *   about the price of 6"), said exactly, "about" or "less than", so the
 *   sentence is true for whatever the two prices are.
 * - The price per month and per day ("About $2.50 a month, or $0.08 a
 *   day"), the year divided, rounded to the currency's smallest unit.
 *
 * Never a former ("was") price, never a percentage (only a public seasonal
 * sale shows one, from the server: `saleReference`). Pure: every amount is
 * in minor units with its currency, and two amounts in different
 * currencies are never compared: nothing is said instead.
 */
import { t } from '@/i18n/index.js';
import { minorDigits } from './offer.js';

/** An amount as a store or the server sent it. */
export interface Amount {
  amountMinor: number;
  currency: string;
  /** The locale the store formats this amount in (Apple's storefront), if it says. */
  locale?: string | undefined;
}

/** Days a yearly plan covers, for the price per day. A calendar fact, not a business value. */
export const DAYS_IN_YEAR = 365;

/** Months a yearly plan covers, for "12 monthly payments". A calendar fact. */
export const MONTHS_IN_YEAR = 12;

/**
 * How close the yearly price may sit above N monthly payments and still be
 * "about the price of N" (2%: $29.99 against 6 × $4.99 = $29.94). Wider
 * than that, the sentence switches to "less than the price of N+1", which
 * is always exactly true. A wording rule, so it lives beside the wording.
 */
export const ABOUT_TOLERANCE = 0.02;

/** How a year compares with monthly payments, always a true sentence. */
export type MonthsAnchor =
  /**
   * yearly ≤ count × monthly: "12 months for the price of {count}." Never
   * "Pay for 6 months, get 12": at $29.99 against 6 × $4.99 = $29.94 that
   * is 5 cents untrue (coordinator, aligned with landing feat/pricing-anchors).
   */
  | { kind: 'exact'; count: number }
  /** within ABOUT_TOLERANCE above count × monthly: "12 months for about the price of {count}." */
  | { kind: 'about'; count: number }
  /** yearly < count × monthly: "12 months for less than the price of {count}." */
  | { kind: 'under'; count: number };

export interface YearAnchors {
  /** Twelve monthly payments, as money: "$59.88". */
  twelveMonthly: string;
  /** The yearly amount compared, as money. */
  yearly: string;
  months: MonthsAnchor | undefined;
}

function valid(amount: Amount | undefined): amount is Amount {
  return (
    amount !== undefined &&
    Number.isFinite(amount.amountMinor) &&
    amount.amountMinor > 0 &&
    amount.currency.trim() !== ''
  );
}

/** An amount in minor units as money, with as many decimals as asked (default: the currency's). */
export function moneyOf(amountMinor: number, currency: string, locale?: string, decimals?: number): string {
  const digits = minorDigits(currency);
  const major = amountMinor / 10 ** digits;
  const places = decimals ?? (amountMinor % 10 ** digits === 0 ? 0 : digits);
  try {
    // The reader's own locale unless the store names one, as `price` in state.ts formats.
    return new Intl.NumberFormat(locale, {
      style: 'currency',
      currency,
      minimumFractionDigits: places,
      maximumFractionDigits: places,
    }).format(major);
  } catch {
    return `${major.toFixed(places)} ${currency}`;
  }
}

/**
 * How a yearly amount compares with twelve monthly ones, or undefined when
 * there is nothing true and worth saying: a missing amount, two currencies,
 * or a year that costs as much as twelve months.
 */
export function monthsAnchor(
  monthly: Amount | undefined,
  yearly: Amount | undefined,
): MonthsAnchor | undefined {
  if (!valid(monthly) || !valid(yearly) || monthly.currency !== yearly.currency) return undefined;
  const ratio = yearly.amountMinor / monthly.amountMinor;
  const near = Math.round(ratio);
  if (near >= 1 && near < MONTHS_IN_YEAR) {
    if (yearly.amountMinor <= near * monthly.amountMinor) return { kind: 'exact', count: near };
    if (ratio - near <= near * ABOUT_TOLERANCE) return { kind: 'about', count: near };
  }
  const above = Math.ceil(ratio);
  // A whole number of months exactly, already handled; past eleven nothing is worth saying.
  if (above >= MONTHS_IN_YEAR || above < 1) return undefined;
  return { kind: 'under', count: above };
}

/** The anchors for a yearly amount beside the monthly plan, or undefined (see `monthsAnchor`). */
export function yearAnchors(
  monthly: Amount | undefined,
  yearly: Amount | undefined,
): YearAnchors | undefined {
  if (!valid(monthly) || !valid(yearly) || monthly.currency !== yearly.currency) return undefined;
  const twelve = monthly.amountMinor * MONTHS_IN_YEAR;
  if (yearly.amountMinor >= twelve) return undefined;
  return {
    twelveMonthly: moneyOf(twelve, monthly.currency, monthly.locale),
    yearly: moneyOf(yearly.amountMinor, yearly.currency, yearly.locale),
    months: monthsAnchor(monthly, yearly),
  };
}

/**
 * A year's amount per day, rounded to the currency's smallest unit:
 * $29.99 is "$0.08", $20.99 "$0.06", ¥3,000 "¥8". Undefined for an amount
 * that rounds to nothing.
 */
export function perDay(yearly: Amount | undefined): string | undefined {
  if (!valid(yearly)) return undefined;
  const minor = Math.round(yearly.amountMinor / DAYS_IN_YEAR);
  if (minor <= 0) return undefined;
  return moneyOf(minor, yearly.currency, yearly.locale, minorDigits(yearly.currency));
}

/** A year's amount per month, rounded to the currency's smallest unit: $29.99 is "$2.50". */
export function perMonth(yearly: Amount | undefined): string | undefined {
  if (!valid(yearly)) return undefined;
  const minor = Math.round(yearly.amountMinor / MONTHS_IN_YEAR);
  if (minor <= 0) return undefined;
  return moneyOf(minor, yearly.currency, yearly.locale, minorDigits(yearly.currency));
}

/** The months anchor as a sentence. */
export function monthsWords(anchor: MonthsAnchor): string {
  switch (anchor.kind) {
    case 'exact':
      return t('anchor.monthsExact', { count: anchor.count });
    case 'about':
      return t('anchor.monthsAbout', { count: anchor.count });
    case 'under':
      return t('anchor.monthsUnder', { count: anchor.count });
  }
}
