/**
 * One shared clock for every countdown on screen (offer presentation spec
 * §4.2, uiux offers spec §3.4): a single timeout chained to the next whole
 * second (or minute, when nobody needs seconds), aligned on the server's
 * clock, stopped when nothing is subscribed and while the page is hidden.
 * A tick calls each subscriber with the time; subscribers re-render only
 * their own text.
 */
import { serverNow } from './serverClock.js';

export type Granularity = 'second' | 'minute';
type Listener = (now: number) => void;

const listeners = new Map<Listener, Granularity>();
let timer: ReturnType<typeof setTimeout> | undefined;

function hidden(): boolean {
  return typeof document !== 'undefined' && document.visibilityState === 'hidden';
}

function step(): number {
  for (const granularity of listeners.values()) if (granularity === 'second') return 1000;
  return 60_000;
}

function schedule(): void {
  if (timer !== undefined) clearTimeout(timer);
  timer = undefined;
  if (listeners.size === 0 || hidden()) return;
  const every = step();
  const now = serverNow();
  // To the next boundary, so every countdown changes together, on the second.
  const wait = every - (((now % every) + every) % every) || every;
  timer = setTimeout(tick, wait + 5);
}

function tick(): void {
  timer = undefined;
  const now = serverNow();
  const minute = Math.floor(now / 1000) % 60 === 0;
  for (const [listener, granularity] of [...listeners]) {
    if (granularity === 'second' || minute || step() === 60_000) listener(now);
  }
  schedule();
}

/** Calls `listener` on every second or minute boundary until the returned stop. */
export function subscribe(granularity: Granularity, listener: Listener): () => void {
  listeners.set(listener, granularity);
  schedule();
  return () => {
    listeners.delete(listener);
    schedule();
  };
}

/** How many listeners are subscribed, for tests. */
export function tickerSize(): number {
  return listeners.size;
}

if (typeof document !== 'undefined') {
  document.addEventListener('visibilitychange', () => {
    if (hidden()) {
      schedule();
      return;
    }
    // Back in view: everyone gets the time at once, then the boundaries again.
    const now = serverNow();
    for (const listener of [...listeners.keys()]) listener(now);
    schedule();
  });
}
