import { useEffect, useState } from 'react';
import { Link } from 'react-router-dom';
import { config } from '@/api/endpoints.js';
import { t } from '@/i18n/index.js';
import { platform } from '@/lib/platform/index.js';
import { useBilling } from '@/features/billing/state.js';
import { settingsPath } from '@/features/settings/paths.js';
import styles from './InviteLine.module.css';

/**
 * One quiet line under the plans (growth study 2026-10-13, "Plan /
 * Upgrade screen"): another way to Pro days, never a button that competes
 * with buying. Said only with the days the server gives (absent while the
 * programme is off), never to somebody who pays (they are thanked, not
 * given days), and not inside the Android and iOS apps until their stores'
 * payment rules have been checked for it.
 */
export function InviteLine({ onOpen }: { onOpen?: () => void }): React.JSX.Element | null {
  const paying = useBilling(
    (s) => s.state?.plan === 'pro' && s.state.provider !== undefined && s.state.provider !== 'manual',
  );
  const store = platform.env.platform === 'android' || platform.env.platform === 'ios';
  const [days, setDays] = useState<number | undefined>(undefined);
  useEffect(() => {
    if (store || paying) return;
    let live = true;
    config
      .get()
      .then((answer) => {
        if (live) setDays(answer.referralDays);
      })
      .catch(() => undefined);
    return () => {
      live = false;
    };
  }, [store, paying]);
  if (store || paying || days === undefined) return null;
  return (
    <p className={styles.line}>
      {t('invite.planLine', { days })}{' '}
      <Link to={`${settingsPath('invite')}?via=plan`} className={styles.link} onClick={onOpen}>
        {t('invite.cardAction')}
      </Link>
    </p>
  );
}
