import { useState } from 'react';
import { useNavigate } from 'react-router-dom';
import { Burst } from '@/components/ui/Burst.js';
import { Icon, type IconName } from '@/components/ui/Icon.js';
import { db } from '@/db/schema.js';
import { modePath } from '@/features/modes/data.js';
import { t } from '@/i18n/index.js';
import { cx } from '@/lib/cx.js';
import { useLiveQuery } from '@/lib/useLiveQuery.js';
import { longDate } from '@/lib/format.js';
import { SealBig } from './art/Seal.js';
import { AlmostThere } from './Celebrate.js';
import type { Purchase } from './purchase.js';
import { useBilling } from './state.js';
import styles from './PurchaseDone.module.css';

/** How many of the learner's own words the tour may name. */
const TOUR_WORDS = 2;

async function newestWords(): Promise<string[]> {
  const words = await db.words.orderBy('createdAt').reverse().limit(TOUR_WORDS).toArray();
  return words.map((word) => word.headword);
}

/**
 * After a purchase the server has confirmed (uiux offers spec §2.8, C18–C19;
 * marketer §6.3): the seal, a small burst, "Pro is yours", a receipt of
 * what was bought and when it renews, then — for somebody who was not in a
 * trial — a three-card tour that uses the learner's own words. Never shown
 * on the store's word alone; 'waiting' says the payment arrived.
 */
export function PurchaseDone({
  purchase,
  onDone,
}: {
  purchase: Purchase;
  onDone: () => void;
}): React.JSX.Element {
  const state = useBilling((s) => s.state);
  const [touring, setTouring] = useState(false);
  if (purchase.stage === 'waiting' && !purchase.approved) return <AlmostThere />;
  if (touring) return <ProTour onDone={onDone} />;

  const offerTitle = state?.offer?.creative?.successTitle;
  const offerLine = state?.offer?.creative?.successLine;
  const bought = purchase.bought;
  const renews = state?.until === undefined ? undefined : longDate(state.until);
  const lead = purchase.fromOffer ? (offerLine ?? t('done.leadOffer')) : t('done.lead');
  return (
    <div className={styles.done} role="status">
      <Burst size="small" />
      <span className={styles.seal}>
        <SealBig />
      </span>
      <h2 className={styles.title}>
        {purchase.fromOffer && offerTitle !== undefined ? offerTitle : t('done.title')}
      </h2>
      <p className={styles.lead}>{lead}</p>
      {bought !== undefined && (
        <dl className={styles.receipt}>
          <dt>{t('done.plan')}</dt>
          <dd>{bought.plan === 'pro_yearly' ? t('done.planYearly') : t('done.planMonthly')}</dd>
          <dt>{t('done.paidToday')}</dt>
          <dd>{bought.billed}</dd>
          {renews !== undefined && (
            <>
              <dt>{t('done.renews')}</dt>
              <dd>{t('done.renewsValue', { date: renews, amount: bought.renewal })}</dd>
            </>
          )}
        </dl>
      )}
      <div className={styles.buttons}>
        {purchase.fromOffer ? (
          <button type="button" className={styles.primary} onClick={onDone}>
            {t('done.lovely')}
          </button>
        ) : (
          <>
            <button type="button" className={styles.secondary} onClick={onDone}>
              {t('done.later')}
            </button>
            <button
              type="button"
              className={styles.primary}
              onClick={() => {
                setTouring(true);
              }}
            >
              {t('done.tour')}
            </button>
          </>
        )}
      </div>
    </div>
  );
}

interface TourCard {
  icon: IconName;
  tint: string;
  title: string;
  line: string;
  action: string;
  to: string;
}

/**
 * "What Pro unlocked": three cards, one at a time, Next/Done and Skip,
 * never auto-advancing. Each uses one of the learner's own words; with
 * none, it says to add one (never a made-up word).
 */
function ProTour({ onDone }: { onDone: () => void }): React.JSX.Element {
  const navigate = useNavigate();
  const words = useLiveQuery(newestWords, [], []);
  const [at, setAt] = useState(0);
  const first = words[0];
  const cards: TourCard[] = [
    {
      icon: 'sparkles',
      tint: styles.tintA ?? '',
      title: t('tour.lex'),
      line: first === undefined ? t('tour.noWord') : t('tour.lexLine', { word: first }),
      action: first === undefined ? t('tour.addWord') : t('tour.lexAction'),
      to: first === undefined ? '/notebook' : '/assistant',
    },
    {
      icon: 'search',
      tint: styles.tintG ?? '',
      title: t('tour.read'),
      line: t('tour.readLine'),
      action: t('tour.readAction'),
      to: '/read',
    },
    {
      icon: 'speaker',
      tint: styles.tintI ?? '',
      title: t('tour.say'),
      line: first === undefined ? t('tour.noWord') : t('tour.sayLine', { word: words[1] ?? first }),
      action: first === undefined ? t('tour.addWord') : t('tour.sayAction'),
      to: first === undefined ? '/notebook' : modePath('sayIt'),
    },
  ];
  const card = cards[at] ?? cards[0];
  const last = at === cards.length - 1;
  return (
    <div
      className={styles.tour}
      role="group"
      aria-roledescription="carousel"
      aria-labelledby="pro-tour-title"
    >
      <h2 id="pro-tour-title" className={styles.tourTitle}>
        {t('tour.title')}
      </h2>
      {card !== undefined && (
        <div
          className={styles.tourCard}
          role="group"
          aria-roledescription="slide"
          aria-label={t('tour.slide', { n: at + 1, total: cards.length })}
        >
          <span className={cx(styles.tourIcon, card.tint)} aria-hidden="true">
            <Icon name={card.icon} size={22} />
          </span>
          <h3>{card.title}</h3>
          <p>{card.line}</p>
          <button
            type="button"
            className={styles.pill}
            onClick={() => {
              onDone();
              void navigate(card.to);
            }}
          >
            {card.action}
          </button>
        </div>
      )}
      <div className={styles.dots} aria-hidden="true">
        {cards.map((one, index) => (
          <i key={one.title} className={index === at ? styles.dotOn : undefined} />
        ))}
      </div>
      <div className={styles.buttons}>
        <button type="button" className={styles.secondary} onClick={onDone}>
          {t('tour.skip')}
        </button>
        <button
          type="button"
          className={styles.primary}
          onClick={() => {
            if (last) onDone();
            else setAt(at + 1);
          }}
        >
          {last ? t('tour.done') : t('tour.next')}
        </button>
      </div>
    </div>
  );
}
