/**
 * The paywall: the offer sheet (uiux offers spec §2.6, C15). It opens from
 * a Pro feature or from Settings; context first (opened from Lex it leads
 * with Lex), then the plans as radio cards, one button with the amount
 * billed today, the trust row and the legal sentence for the chosen plan,
 * and the legal links (Restore purchases in the iPhone app). The purchase
 * itself happens in the seller's own sheet — Paddle's overlay on the web,
 * Google Play's inside the Android app, Apple's inside the iPhone app.
 *
 * Nothing here decides that anyone has paid. On the web the plan is read
 * from the server again, because the server learns from Paddle's own
 * notification; in the apps the token or transaction the store returns is
 * sent to the server, which asks Google or Apple what it is worth.
 */
export function Upgrade({
  onClose,
  occasion = 'settings',
  moment,
}: {
  onClose: () => void;
  /** Where the sheet was opened from, which decides its head. */
  occasion?: Occasion;
  /**
   * The moment that opened it, when it is not the occasion's own (the card
   * after a milestone). The server may give the moment offer here.
   */
  moment?: ApiMomentKind | undefined;
}): React.JSX.Element {
  const state = useBilling((s) => s.state);
  const limits = usePlanLimits();
  const refresh = useBilling((s) => s.refresh);
  const askMoment = useBilling((s) => s.moment);
  const purchase = usePurchase();
  const { busy, error, stage, approval, approved } = purchase;
  const apple = onIOS();
  const restore = useAppStoreRestore(purchase.finish);
  // Read again with every answer: a moment offer given as the sheet opens
  // starts at the server's now, after the sheet's first frame.
  const now = new Date(serverNow());
  // An offer whose end passed while the sheet was open: its card goes at
  // once (§10.1, within a second), before the server is read again.
  const [ended, setEnded] = useState<string | undefined>(undefined);
  // A client that may not sell shows no price and no way to pay, however it
  // got here: a locked feature can open this sheet without asking first,
  // and inside the iPhone app a Paddle button would break the App Store's
  // rules (see `onIOS`).
  const sells = canBuyHere(state);
  const live = sells ? openOffer(state, now) : undefined;
  const offer = live !== undefined && live.id === ended ? undefined : live;
  const model = useKeepPro(offer);
  // The moment this sheet is (moment offer §5): asked once as it opens.
  const kind = moment ?? momentKindFor(occasion);
  useEffect(() => {
    noteSellingShown();
  }, []);
  // The paywall funnel: the sheet opened here (a milestone card's own place).
  const place = moment !== undefined ? 'moment' : occasion;
  useEffect(() => {
    sendPaywallEvent(place, 'opened');
  }, [place]);
  // Once the plan is known (the store asks at most once per kind a run).
  const known = state !== null;
  useEffect(() => {
    if (known && kind !== undefined) void askMoment(kind);
  }, [known, kind, askMoment]);
  const momentOffer = isMomentOffer(offer);
  const trial = runningTrial(state, now) !== undefined;
  const trustId = useId();
  const legalId = useId();
  const offerId = model.choices.find((one) => one.offer !== undefined)?.offer?.id;
  useEffect(() => {
    if (offerId !== undefined) sendOfferEvent(offerId, 'shown', 'offer_sheet');
  }, [offerId]);
  const offerChoice = model.choices.find((one) => one.offer !== undefined);
  const look = offer?.creative?.look;

  if (stage !== 'choosing' || approved) {
    return (
      <Sheet label={t('upgrade.title')} onClose={onClose}>
        <PurchaseDone purchase={purchase} onDone={onClose} />
      </Sheet>
    );
  }

  const titleId = `upgrade-${occasion}`;
  const square = offer?.creative?.images.find((image) => image.role === 'square');
  return (
    <Sheet label={t(`sheet.title.${occasion}`)} onClose={onClose}>
      <div className={styles.body}>
        <div className={styles.head}>
          <span className={styles.headArt} aria-hidden="true">
            {square === undefined ? <SmallArt /> : <CampaignImage image={square} sizes="56px" />}
          </span>
          <div>
            <h2 className={styles.headTitle} id={titleId}>
              {t(`sheet.title.${occasion}`)}
            </h2>
            <p className={styles.headLead}>
              {occasion === 'resting' || occasion === 'aiIdle'
                ? cardsLead(limits, t(`pro.${occasion}.line`))
                : t(`pro.${occasion}.line`)}
            </p>
          </div>
          <button type="button" className={styles.close} onClick={onClose} aria-label={t('action.close')}>
            <Icon name="close" size={20} weight={2} />
          </button>
        </div>

        <PerkChips occasion={occasion} />

        {sells && model.choices.length > 0 && (
          <>
            {purchase.notice !== null && (
              <p className={styles.note} role="status">
                {purchase.notice}
              </p>
            )}
            {momentOffer && offerChoice !== undefined && <MomentLead choice={offerChoice} />}
            {ended !== undefined && offer === undefined && <EndedLine />}
            <PlanPicker
              model={model}
              legend={trial ? t('pick.legend') : t('pick.legendGet')}
              legendHidden
              disabled={busy !== null}
              countdown={{
                surface: 'opened',
                label: countdownLabel(offerChoice?.badge),
                liveSecondsFromHours: look?.liveSecondsFromHours ?? 24,
                style: momentOffer ? 'moment' : (look?.countdownStyle ?? 'auto'),
                pips: !momentOffer,
                onEnded: () => {
                  if (offer !== undefined) setEnded(offer.id);
                  void refresh();
                },
              }}
            />
            <BuyButton
              model={model}
              trial={trial}
              busy={busy !== null}
              disabled={busy !== null}
              describedBy={`${trustId} ${legalId}`}
              onBuy={(choice) => {
                sendPaywallEvent(place, 'checkout_started');
                purchase.buy(choice.id, choice.offer, { billed: choice.billed, renewal: choice.renewal });
              }}
            />
            <BuyFoot model={model} trial={trial} ids={{ trust: trustId, legal: legalId }} />
            {momentOffer && <p className={styles.note}>{t('moment.doNothing')}</p>}
          </>
        )}

        {(!sells || model.choices.length === 0) && (
          <p className={styles.note}>{apple ? t('upgrade.notInApp') : t('upgrade.closed')}</p>
        )}
        {approval && (
          <p className={styles.approval} role="status">
            {t('upgrade.pendingApproval')}
          </p>
        )}
        {/* Another way to Pro days, quietly under the plans (features/invite). */}
        <InviteLine onOpen={onClose} />
        {error !== null && (
          <p className={styles.error} role="alert">
            {error}
          </p>
        )}
        {sells && model.choices.length > 0 && (
          <LegalRow store={storeHere()} restore={apple ? restore : undefined} disabled={busy !== null} />
        )}
      </div>
    </Sheet>
  );
}

/**
 * The moment offer's head (§6): what it is, in the seller's words, and that
 * it is made once (true because the server gives it once per account).
 */
function MomentLead({ choice }: { choice: PlanChoice }): React.JSX.Element {
  return (
    <div className={styles.momentLead}>
      <p className={styles.momentTitle}>
        {t('moment.justForYou', { first: choice.billed, renewal: choice.renewal })}
      </p>
      <p className={styles.note}>{t('moment.once')}</p>
    </div>
  );
}

/**
 * What else Pro is, as chips (uiux §2.6), the occasion's own feature left
 * out. The two Pro practice modes are named only where the server has
 * switched them on: a perk somebody cannot find is a promise the app does
 * not keep. The AI cards' number is the server's (`GET /config` `limits`),
 * and each perk is one plain line rather than a feature name.
 */
function PerkChips({ occasion }: { occasion: Occasion }): React.JSX.Element {
  const srs = useLiveQuery(loadSrsView, null, []);
  const limits = usePlanLimits();
  const sayIt = srs !== null && shows(srs, 'sayIt');
  const chips: { key: string; icon: IconName; label: string; skip: boolean }[] = [
    { key: 'lex', icon: 'sparkles', label: t('chip.lex'), skip: occasion === 'lex' },
    { key: 'read', icon: 'search', label: t('chip.read'), skip: occasion === 'readText' },
    { key: 'say', icon: 'speaker', label: t('chip.sayIt'), skip: occasion === 'sayIt' || !sayIt },
    {
      key: 'cards',
      icon: 'cards',
      label: cardsPerk(limits),
      skip: occasion === 'resting' || occasion === 'aiIdle',
    },
    { key: 'voice', icon: 'mic', label: t('chip.voice'), skip: occasion === 'voice' },
    { key: 'notebooks', icon: 'notebook', label: t('chip.notebooks'), skip: occasion === 'notebook' },
  ];
  return (
    <ul className={styles.chips} aria-label={t('chip.label')}>
      {chips
        .filter((chip) => !chip.skip)
        .map((chip) => (
          <li key={chip.key}>
            <Icon name={chip.icon} size={14} />
            {chip.label}
          </li>
        ))}
    </ul>
  );
}

/**
 * The row in Settings. It shows the plan, and offers to upgrade only when
 * the server says this client may sell.
 */
export function PlanRow({
  rowClass,
  labelClass,
  valueClass,
  onPlanPage = false,
  withoutOffer = false,
}: {
  rowClass: string | undefined;
  labelClass: string | undefined;
  valueClass: string | undefined;
  /**
   * The free Plan page draws its own "Get Lexpad Pro" button above (app
   * audit 2026-10-22); the row keeps everything else (Restore purchases in
   * the iPhone app) and leaves out its own offer.
   */
  withoutOffer?: boolean;
  /**
   * Drawn on the Plan page itself, under its own head and cards: the trial
   * row and the way to buy are the page, so they are not repeated here.
   */
  onPlanPage?: boolean;
}): React.JSX.Element {
  const state = useBilling((s) => s.state);
  const limits = usePlanLimits();
  const [open, setOpen] = useState(false);
  const [opening, setOpening] = useState(false);
  const [failed, setFailed] = useState(false);
  const notebook = useLiveQuery(getActiveNotebook, undefined, []);
  // Restoring in Settings ends on the plan row itself, which then says Pro.
  const restore = useAppStoreRestore(() => undefined);

  // Narrowing on the state itself, so its other fields are known below.
  const pro = state !== null && state.plan === 'pro' ? state : null;
  // A trial is Pro, with a date; buying during it starts the paid plan that
  // day, so the offer stays open beside it (Settings → Plan is one of the
  // places Pro may be offered).
  const [now] = useState(() => new Date());
  const trial = runningTrial(state, now);
  const prices = paidPrices(state);
  // A notebook Lexpad never charges for gets the opposite of a paywall. It
  // is checked before the offer, so somebody who is already free can never
  // be shown a price for what they already have — the one mistake this row
  // must not make.
  const free = pro === null ? freeSide(state, notebook?.targetLang, notebook?.meaningLang) : undefined;
  // During the trial the plan is Pro, so `free` above is not worked out; a
  // notebook Lexpad never charges for still hears nothing about a price.
  const freeHere = free ?? freeSide(state, notebook?.targetLang, notebook?.meaningLang);
  const offer =
    (pro === null || trial !== undefined) && freeHere === undefined && canBuyHere(state) && prices.length > 0;
  // An open offer (trial-offers design §2.2) is shown, with both its prices,
  // on the Plan page only, so every way to buy leads there while it is open.
  const offerOpen = openOffer(state, now) !== undefined;
  // The cheapest paid plan, so the row can carry a price rather than make
  // somebody open a sheet to find one.
  const cheapest = prices.reduce<(typeof prices)[number] | undefined>(
    (best, p) => (best === undefined || p.amountMinor < best.amountMinor ? p : best),
    undefined,
  );
  // A price on the Plan page is the Plan page with prices: no rating
  // request in this run (sellingSignals.ts). The same row in Settings is
  // the plan's name with a price beside it, not a sales screen.
  const pricedOnPlanPage = onPlanPage && offer && trial === undefined && cheapest !== undefined;
  useEffect(() => {
    if (pricedOnPlanPage) noteSellingShown();
  }, [pricedOnPlanPage]);

  /**
   * Sends someone to the provider's own page to cancel or change a card.
   * The link is short-lived, so it is fetched at the moment of the tap
   * rather than held on the screen.
   */
  const manage = (): void => {
    setOpening(true);
    setFailed(false);
    billingApi
      .portal()
      .then((portal) => {
        // Only the provider's own portal; anything else is treated as a
        // link that could not be opened.
        const target = safeExternalUrl(portal.cancelUrl ?? portal.url, 'billingPortal');
        if (target === undefined) {
          setFailed(true);
          return;
        }
        // A new tab, because leaving the app to cancel and having no way
        // back would be a poor way to treat someone who is leaving.
        window.open(target.href, '_blank', 'noopener,noreferrer');
      })
      .catch(() => {
        setFailed(true);
      })
      .finally(() => {
        setOpening(false);
      });
  };

  return (
    <>
      {free !== undefined && (
        <button
          type="button"
          className={cx(rowClass, styles.button, styles.freeRow)}
          onClick={() => {
            setOpen(true);
          }}
        >
          <span className={labelClass}>{t('free.row')}</span>
          <span className={valueClass}>{t('free.rowNote')}</span>
        </button>
      )}
      {/* The trial is a button on every client, selling or not: it opens
          the Plan page, which has the whole story (trial-offers §2.1). */}
      {trial !== undefined && !onPlanPage && (
        <PlanPageRow
          className={cx(rowClass, styles.button, styles.trialRow)}
          labelClass={labelClass}
          valueClass={valueClass}
          label={trialStatus(trial.endsAt, now)}
          value={t('trial.rowUntil', { date: trialDate(trial.endsAt, now) })}
        />
      )}
      {trial === undefined && !offer && free === undefined && (
        <div className={rowClass}>
          <span className={labelClass}>{t('upgrade.plan')}</span>
          <span className={valueClass}>{planWords(pro)}</span>
        </div>
      )}
      {pro?.canceled === true &&
        pro.provider !== undefined &&
        pro.provider !== 'manual' &&
        trial === undefined && <CancelReason />}
      {offer && trial === undefined && offerOpen && cheapest !== undefined && !onPlanPage && (
        <PlanPageRow
          className={cx(rowClass, styles.button, styles.offerRow)}
          labelClass={labelClass}
          valueClass={valueClass}
          label={t('upgrade.row')}
          value={rowNote(limits, formatPrice(cheapest))}
        />
      )}
      {offer && trial === undefined && !offerOpen && cheapest !== undefined && !withoutOffer && (
        <button
          type="button"
          className={cx(rowClass, styles.button, styles.offerRow)}
          onClick={() => {
            setOpen(true);
          }}
        >
          <span className={labelClass}>{t('upgrade.row')}</span>
          <span className={valueClass}>{rowNote(limits, formatPrice(cheapest))}</span>
        </button>
      )}
      {managedInPlay(state) && (
        <button
          type="button"
          className={cx(rowClass, styles.button)}
          onClick={() => {
            // Play is the seller here, so its own screen is the only place
            // that can cancel or change a card. There is no link of ours to
            // fetch and nothing that can be down.
            window.open(PLAY_SUBSCRIPTIONS_URL, '_blank', 'noopener,noreferrer');
          }}
        >
          <span className={labelClass}>{t('upgrade.manage')}</span>
          <span className={valueClass}>{t('upgrade.manageInPlay')}</span>
        </button>
      )}
      {managedInAppStore(state) && (
        <button
          type="button"
          className={cx(rowClass, styles.button)}
          onClick={() => {
            // Apple is the seller, so its own sheet (in the iPhone app) or
            // its subscriptions page (anywhere else) is the only place that
            // can change or cancel this. There is no link of ours to fetch.
            if (onIOS()) void manageAppStoreSubscription();
            else window.open(APP_STORE_SUBSCRIPTIONS_URL, '_blank', 'noopener,noreferrer');
          }}
        >
          <span className={labelClass}>{t('upgrade.manage')}</span>
          <span className={valueClass}>{t('upgrade.manageInAppStore')}</span>
        </button>
      )}
      {onIOS() && canBuyHere(state) && (
        <button
          type="button"
          className={cx(rowClass, styles.button)}
          disabled={restore.status === 'restoring'}
          onClick={restore.run}
        >
          <span className={labelClass}>{t('upgrade.restore')}</span>
          <span className={valueClass} role="status">
            {restoreWords(restore.status) ?? t('upgrade.restoreNote')}
          </span>
        </button>
      )}
      {canManage(state) && (
        <button type="button" className={cx(rowClass, styles.button)} disabled={opening} onClick={manage}>
          <span className={labelClass}>{t('upgrade.manage')}</span>
          <span className={valueClass}>
            {opening
              ? t('upgrade.manageOpening')
              : failed
                ? t('upgrade.manageFailed')
                : t('upgrade.manageNote')}
          </span>
        </button>
      )}
      {open &&
        (free === undefined ? (
          <Upgrade
            onClose={() => {
              setOpen(false);
            }}
          />
        ) : (
          <FreeForYou
            side={free.side}
            code={free.code}
            onClose={() => {
              setOpen(false);
            }}
          />
        ))}
    </>
  );
}

/**
 * A plan row that opens the Plan page, and tells the offer's funnel it was
 * opened from Settings when there is an offer.
 */
function PlanPageRow({
  className,
  labelClass,
  valueClass,
  label,
  value,
}: {
  className: string;
  labelClass: string | undefined;
  valueClass: string | undefined;
  label: string;
  value: string;
}): React.JSX.Element {
  const navigate = useNavigate();
  const offer = useBilling((s) => s.state?.offer);
  return (
    <button
      type="button"
      className={className}
      onClick={() => {
        if (offer !== undefined) sendOfferEvent(offer.id, 'opened', 'settings_row');
        void navigate(settingsPath('plan'));
      }}
    >
      <span className={labelClass}>{label}</span>
      <span className={valueClass}>{value}</span>
    </button>
  );
}
