/**
 * The Pro offer's funnel for the operators (the data plan, owner 22 Oct
 * 2026): where it was seen, where its sheet was opened, where a checkout
 * began. The server keeps one row per account, place, step and day, and
 * reads trials and payments from the subscriptions itself, so nothing about
 * money is sent from here. Fire and forget, never retried; this keeps a
 * small guard so one run sends each step at most once a day.
 */
import { billing as billingApi } from '@/api/endpoints.js';
import type { ApiPaywallEventInput } from '@/api/types.js';

export type PaywallPlace = ApiPaywallEventInput['place'];
export type PaywallStep = ApiPaywallEventInput['event'];

const sent = new Set<string>();

export function sendPaywallEvent(place: PaywallPlace, event: PaywallStep): void {
  const key = `${place}:${event}:${new Date().toDateString()}`;
  if (sent.has(key)) return;
  sent.add(key);
  try {
    void billingApi.paywallEvent({ place, event }).catch(() => undefined);
  } catch {
    // Nothing a learner should ever hear about.
  }
}

/** For tests: forget what was sent. */
export function forgetPaywallEvents(): void {
  sent.clear();
}
