import { useState } from 'react';
import { cx } from '@/lib/cx.js';
import styles from './Burst.module.css';
import { BURST_PIECES, prefersReducedMotion } from './motionPrefs.js';

/** How far a piece falls, in px: past the summary's head, or around a sheet's badge and no further. */
const FALL_PX = { top: 300, center: 130 } as const;

/**
 * Whether confetti is worth drawing here at all: never in a hidden tab
 * (nobody sees it, and it would play on return), never where the learner
 * asked for less data, and half as much on a slow screen or a phone with
 * little memory.
 */
function piecesFor(wanted: number): number {
  if (typeof document !== 'undefined' && document.hidden) return 0;
  const media = (query: string): boolean =>
    typeof window.matchMedia === 'function' && window.matchMedia(query).matches;
  if (media('(prefers-reduced-data: reduce)')) return 0;
  const memory = (navigator as Navigator & { deviceMemory?: number }).deviceMemory;
  if (media('(update: slow)') || (memory !== undefined && memory <= 2)) return Math.ceil(wanted / 2);
  return wanted;
}

/**
 * A small, fixed spread: the same piece always falls the same way, so a
 * screenshot is the same twice and nothing random is called while rendering.
 */
function spread(index: number, count: number): { left: number; dx: number; rot: number; delay: number } {
  const golden = (index * 0.618_034) % 1;
  return {
    left: count === 1 ? 50 : 4 + (index / (count - 1)) * 92,
    dx: Math.round((golden - 0.5) * 120),
    rot: Math.round(240 + golden * 420) * (index % 2 === 0 ? 1 : -1),
    delay: (index % 6) * 60 + Math.round(golden * 90),
  };
}

/**
 * Confetti behind a moment (the session summary's head, the celebration
 * sheet, the Pro sheet). An absolute layer that never takes a tap, a few
 * CSS pieces moved by `transform` and `opacity` only, and gone from the DOM
 * when the last piece lands. Under reduced motion nothing falls; three
 * drawn sparkles stand in, so the moment still looks like one.
 */
export function Burst({
  size = 'small',
  origin = 'top',
  className,
}: {
  /** Small for a sheet's own moment (Pro), burst for the summary, takeover for the celebration sheet. */
  size?: keyof typeof BURST_PIECES;
  origin?: 'top' | 'center';
  className?: string | undefined;
}): React.JSX.Element | null {
  const pieces = BURST_PIECES[size];
  // Decided once, as the moment arrives: a change of mind mid-fall would
  // either cut the pieces off or start them again.
  const [plan] = useState(() =>
    prefersReducedMotion() ? { still: true, count: 0 } : { still: false, count: piecesFor(pieces) },
  );
  const [left, setLeft] = useState(plan.count);

  if (plan.still) {
    return (
      <svg className={cx(styles.sparkles, className)} viewBox="0 0 120 60" aria-hidden="true">
        <path className={styles.sparkleA} d="M18 14l2.4 6.6L27 23l-6.6 2.4L18 32l-2.4-6.6L9 23l6.6-2.4z" />
        <path
          className={styles.sparkleB}
          d="M100 6l1.8 4.9 4.9 1.8-4.9 1.8-1.8 4.9-1.8-4.9-4.9-1.8 4.9-1.8z"
        />
        <path className={styles.sparkleC} d="M96 40l1.5 4 4 1.5-4 1.5-1.5 4-1.5-4-4-1.5 4-1.5z" />
      </svg>
    );
  }
  if (left <= 0) return null;

  const count = plan.count;
  return (
    <div
      className={cx(styles.layer, size === 'takeover' && styles.long, className)}
      aria-hidden="true"
      data-burst=""
    >
      {Array.from({ length: count }, (_, index) => {
        const one = spread(index, count);
        return (
          <span
            key={index}
            className={cx(styles.piece, index % 4 === 3 && styles.round)}
            style={
              {
                left: `${String(one.left)}%`,
                '--dx': `${String(one.dx)}px`,
                '--rot': `${String(one.rot)}deg`,
                '--fall': `${String(FALL_PX[origin])}px`,
                animationDelay: `${String(one.delay)}ms`,
              } as React.CSSProperties
            }
            onAnimationEnd={() => {
              setLeft((n) => n - 1);
            }}
          />
        );
      })}
    </div>
  );
}
