import { memo, useEffect, useRef, useState } from 'react';
import { Icon } from '@/components/ui/Icon.js';
import { prefersReducedMotion } from '@/components/ui/motionPrefs.js';
import { getMeta } from '@/db/schema.js';
import { t } from '@/i18n/index.js';
import { cx } from '@/lib/cx.js';
import { serverNow } from '@/lib/serverClock.js';
import { subscribe } from '@/lib/ticker.js';
import { useLiveQuery } from '@/lib/useLiveQuery.js';
import { useAuth } from '@/features/auth/session.js';
import {
  COUNTDOWN_PIPS,
  countdownView,
  eventStage,
  type CountdownEventStage,
  type CountdownStyle,
  type CountdownSurface,
} from './countdown.js';
import { zoneNameIfOther } from './moment.js';
import { paused } from './countdownPause.js';
import styles from './OfferCountdown.module.css';

const HOUR = 3_600_000;

export interface OfferCountdownProps {
  /** The account's own closing instant. Without a readable one there is no countdown at all. */
  closesAt: string | undefined;
  surface: CountdownSurface;
  /** "Early price": what is ending. */
  label?: string | undefined;
  /** The operator's live-seconds window (0 to 24 hours; the server never sends more than 24). */
  liveSecondsFromHours?: number;
  style?: CountdownStyle;
  /** On the dark hero ground (the Today banner). */
  tone?: 'page' | 'hero';
  /** The seven day pips in the "days left" stage (one segmented meter per screen). */
  pips?: boolean;
  /** Each stage once, for the funnel's `countdownStage`. */
  onStage?: (stage: CountdownEventStage) => void;
  /** The deadline passed while on screen: read the plan again. */
  onEnded?: () => void;
}

/**
 * The countdown to an offer's own `closesAt` (offer presentation spec
 * §4.1–4.2, uiux offers spec §3). One shared ticker drives it, aligned to
 * the second and on the server's clock; it re-renders only itself.
 *
 * It renders nothing without a real, future `closesAt`: never a made-up
 * deadline, never one that already passed when the screen was drawn. At
 * zero while on screen it says "This price has ended" and calls `onEnded`
 * at once, so the plan is read again and the full price comes back.
 *
 * Screen readers hear one static sentence per stage (the ticking digits
 * are hidden), and a polite announcement only on entering the last hour
 * and at the end. With reduced motion, Celebrations off or the pause
 * pressed, it moves in minute steps.
 */
export const OfferCountdown = memo(function OfferCountdown({
  closesAt,
  surface,
  label,
  liveSecondsFromHours = 24,
  style = 'auto',
  tone = 'page',
  pips = false,
  onStage,
  onEnded,
}: OfferCountdownProps): React.JSX.Element | null {
  const closes = closesAt === undefined ? Number.NaN : Date.parse(closesAt);
  const [now, setNow] = useState(() => serverNow());
  // Whether the deadline was still ahead when this countdown first drew:
  // one already past is not a countdown, it is nothing.
  const [aheadAtStart] = useState(() => !Number.isNaN(closes) && closes > serverNow());
  const [pausedHere, setPausedHere] = useState(() => paused.has(surface));
  const celebrationsOff = useLiveQuery(async () => (await getMeta('celebrate'))?.off === true, false, []);
  // The device's own clock, named only when it is not the account's zone
  // (moment offer §10.1); the other styles keep their words.
  const accountZone = useAuth((s) => s.user?.timezone);
  const zoneName = style === 'moment' ? zoneNameIfOther(accountZone) : undefined;
  const calm = pausedHere || celebrationsOff || prefersReducedMotion();
  const box = useRef<HTMLSpanElement>(null);
  const [visible, setVisible] = useState(true);
  const [announce, setAnnounce] = useState('');

  const view = Number.isNaN(closes)
    ? undefined
    : countdownView({
        closesAt: new Date(closes),
        now,
        surface,
        liveSecondsFromHours,
        style,
        calm,
        label,
        zoneName,
      });
  const every = view?.every ?? 'minute';
  const live = aheadAtStart && view !== undefined && view.stage !== 'ended';

  // Off screen, nothing ticks for it.
  useEffect(() => {
    const element = box.current;
    if (element === null || typeof IntersectionObserver === 'undefined') return;
    const observer = new IntersectionObserver((entries) => {
      setVisible(entries.some((entry) => entry.isIntersecting));
    });
    observer.observe(element);
    return () => {
      observer.disconnect();
    };
  }, []);

  useEffect(() => {
    if (!live || !visible) return;
    setNow(serverNow());
    return subscribe(every, (at) => {
      setNow(at);
    });
  }, [live, visible, every]);

  // The end, while on screen: said, then the plan is read again.
  const stage = view?.stage;
  const ended = aheadAtStart && stage === 'ended';
  const endedSent = useRef(false);
  useEffect(() => {
    if (!ended || endedSent.current) return;
    endedSent.current = true;
    setAnnounce(t('countdown.srEnded'));
    onEnded?.();
  }, [ended, onEnded]);

  // Entering the last hour is announced once; nothing else is.
  const lastHour = live && closes - now <= HOUR;
  const lastHourSaid = useRef(false);
  useEffect(() => {
    if (!lastHour || lastHourSaid.current) return;
    lastHourSaid.current = true;
    setAnnounce(t('countdown.srLastHour'));
  }, [lastHour]);

  const lastStage = useRef<CountdownEventStage | undefined>(undefined);
  useEffect(() => {
    if (stage === undefined || !aheadAtStart) return;
    const mapped = eventStage(stage);
    if (lastStage.current === mapped) return;
    lastStage.current = mapped;
    onStage?.(mapped);
  }, [stage, aheadAtStart, onStage]);

  if (!aheadAtStart || view === undefined) return null;

  return (
    <span ref={box} className={cx(styles.wrap, tone === 'hero' && styles.onHero)}>
      <span className={cx(styles.line, view.soon && styles.soon)} role="timer" aria-live="off">
        <span aria-hidden="true" className={styles.lineInner}>
          <Icon name="clock" size={15} weight={1.9} />
          <span>{view.text}</span>
          {view.digits !== undefined && (
            <bdi dir="ltr" className={styles.digits}>
              {view.digits}
            </bdi>
          )}
        </span>
        <span className="sr-only">{view.sr}</span>
        {view.digits !== undefined && (
          <button
            type="button"
            className={styles.pause}
            aria-label={t('countdown.pause')}
            onClick={() => {
              paused.add(surface);
              setPausedHere(true);
            }}
          >
            <Icon name="pause" size={13} weight={2.2} />
          </button>
        )}
      </span>
      {view.under !== undefined && (
        <span className={styles.under} aria-hidden="true">
          {view.under}
        </span>
      )}
      {view.small !== undefined && (
        <span className={styles.under} aria-hidden="true">
          {view.small}
        </span>
      )}
      {pips && view.pipsOpen !== undefined && (
        <span className={styles.pips} aria-hidden="true">
          {Array.from({ length: COUNTDOWN_PIPS }, (_, index) => (
            <i key={index} className={index < (view.pipsOpen ?? 0) ? styles.pipOpen : styles.pipGone} />
          ))}
        </span>
      )}
      <span className="sr-only" aria-live="polite">
        {announce}
      </span>
    </span>
  );
});
